cat >> tests/test_fulfilment.py <<'EOF'


def test_low_stock_strictly_below_threshold_sorted_by_stock_then_sku(shop):
    shop.catalog.handle_add_product({"sku": "CUP", "name": "Cup", "unit_price_cents": 900, "on_hand": 5})
    shop.catalog.handle_add_product({"sku": "APP", "name": "App", "unit_price_cents": 900, "on_hand": 5})
    response = shop.fulfilment.handle_low_stock(50)
    assert response.status == 200
    assert response.body == {"products": [
        {"sku": "APP", "name": "App", "on_hand": 5},
        {"sku": "CUP", "name": "Cup", "on_hand": 5},
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5},
    ]}


def test_low_stock_threshold_is_exclusive(shop):
    assert shop.fulfilment.handle_low_stock(5).body == {"products": []}
    assert shop.fulfilment.handle_low_stock(6).body["products"] == [
        {"sku": "LAMP", "name": "Lamp", "on_hand": 5}]


def test_low_stock_zero_threshold_is_empty(shop):
    assert shop.fulfilment.handle_low_stock(0).body == {"products": []}


def test_low_stock_reflects_stock_movements(shop):
    shop.orders.handle_create({"customer_id": "c1", "items": [{"sku": "PEN", "quantity": 95}]})
    assert shop.fulfilment.handle_low_stock(10).body == {"products": [
        {"sku": "PEN", "name": "Pen", "on_hand": 5}]}


def test_low_stock_rejects_invalid_threshold(shop):
    for bad in (-1, True, False, "5", 2.5, None):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400, bad
        assert "error" in response.body
EOF
