"""Fulfilment endpoints for the warehouse."""

from __future__ import annotations

from orders.application.errors import Conflict, CustomerNotFound, OrderNotFound
from orders.application.fulfilment_service import FulfilmentService
from typing import Any

from orders.application.errors import ProductNotFound
from orders.controllers.http import (InvalidRequest, Response, bad_request, conflict, not_found,
                                     require_non_negative_int, require_positive_int, require_str)
from orders.domain.fulfilment import PackingSlip


def packing_slip_body(slip: PackingSlip) -> dict:
    return {
        "order_id": slip.order_id,
        "customer_name": slip.customer_name,
        "lines": [{"sku": line.sku, "name": line.name, "quantity": line.quantity}
                  for line in slip.lines],
    }


class FulfilmentController:
    def __init__(self, service: FulfilmentService) -> None:
        self._service = service

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            slip = self._service.packing_slip(order_id)
        except OrderNotFound:
            return not_found("order")
        except Conflict as exc:
            return conflict(exc)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, packing_slip_body(slip))

    def handle_restock(self, request: dict[str, Any]) -> Response:
        try:
            sku = require_str(request, "sku")
            quantity = require_positive_int(request.get("quantity"), "quantity")
        except InvalidRequest as exc:
            return bad_request(exc)
        try:
            on_hand = self._service.restock(sku, quantity)
        except ProductNotFound:
            return not_found("product")
        return Response(200, {"sku": sku, "on_hand": on_hand})

    def handle_low_stock(self, threshold: Any) -> Response:
        try:
            limit = require_non_negative_int(threshold, "threshold")
        except InvalidRequest as exc:
            return bad_request(exc)
        levels = self._service.low_stock(limit)
        return Response(200, {"products": [{"sku": level.sku, "name": level.name, "on_hand": level.on_hand}
                                           for level in levels]})

def place(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_packing_slip_lists_lines_in_item_order_with_catalogue_names(shop):
    oid = place(shop, "c2", ("PEN", 3), ("BOOK", 1), ("LAMP", 2)).body["order_id"]
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 200
    assert response.body == {
        "order_id": oid,
        "customer_name": "Grace",
        "lines": [
            {"sku": "PEN", "name": "Pen", "quantity": 3},
            {"sku": "BOOK", "name": "Book", "quantity": 1},
            {"sku": "LAMP", "name": "Lamp", "quantity": 2},
        ],
    }


def test_packing_slip_unknown_order_is_404(shop):
    response = shop.fulfilment.handle_packing_slip("ord-9999")
    assert response.status == 404
    assert response.body == {"error": "order not found"}


def test_packing_slip_cancelled_order_is_409(shop):
    oid = place(shop, "c1", ("BOOK", 1)).body["order_id"]
    shop.orders.handle_cancel(oid)
    response = shop.fulfilment.handle_packing_slip(oid)
    assert response.status == 409
    assert "cancelled" in response.body["error"]


